(() => {
  const stage=document.querySelector('#web-stage'),layer=document.querySelector('#targets'),effects=document.querySelector('#web-effects');
  const noMotion=matchMedia('(prefers-reduced-motion: reduce)').matches;const svgNS='http://www.w3.org/2000/svg';const base=[[180,150],[500,125],[820,165],[240,325],[550,320],[830,380]];
  const villains=[
    {name:'Green Goblin',tag:'GLIDER INTERCEPT',brief:'Track the moving glider signals and web them before the Goblin escapes. Classic webs deal two containment points per hit.',color:'#9ce17c',svg:'<path d="m18 20 12-14 20 8 20-8 12 14-8 48-24 21-24-21Z" fill="#52874b" stroke="#b9dc86" stroke-width="2"/><path d="m27 35 18 6-15 8m43-14-18 6 15 8" fill="#f8df72"/><path d="m35 66 15-8 15 8-15 9Z" fill="#172e25"/><path d="M8 85 50 75 92 85 70 96H30Z" fill="#8c91a2"/>'},
    {name:'Doctor Octopus',tag:'TENTACLE LOCKDOWN',brief:'Catch the moving arm controls to lock down Doc Ock’s machinery. Use a web net to cover several weak points at once.',color:'#e5b96a',svg:'<g fill="none" stroke="#b5a07a" stroke-width="5"><path d="M30 68Q-5 48 10 15M70 68q35-20 20-53M30 72Q-5 85 13 99M70 72q35 13 17 27"/></g><path d="M25 98V67l25-9 25 9v31Z" fill="#665a3c"/><path d="M32 22q18-12 36 0v34L50 72 32 56Z" fill="#c19470"/><path d="M29 29q0-25 21-23 24-2 22 23L59 20 44 21Z" fill="#654835"/><g fill="#172631" stroke="#cbac69" stroke-width="2"><circle cx="39" cy="39" r="9"/><circle cx="61" cy="39" r="9"/><path d="M48 39h4"/></g>'},
    {name:'Electro',tag:'POWER GRID SURGE',brief:'Web the charged nodes to contain Electro’s power surge. Triple burst can catch nearby nodes in one shot.',color:'#70cfff',svg:'<path d="m50 5 7 24 20-11-8 24 26 8-26 8 8 24-20-11-7 24-7-24-20 11 8-24-26-8 26-8-8-24 20 11Z" fill="#efcf61"/><path d="M35 25h30v38L50 82 35 63Z" fill="#529cc5"/><path d="m39 43 8 4m14-4-8 4" stroke="#f2fbff" stroke-width="3"/><path d="m43 60 7 7 7-7" fill="none" stroke="#c7f2ff" stroke-width="2"/>'},
    {name:'Mysterio',tag:'ILLUSION BREAKER',brief:'Clear the moving illusion projectors to reveal Mysterio. Follow their positions carefully; every successful catch weakens the illusion.',color:'#a3e3d3',svg:'<path d="m10 100 10-39 30 22 30-22 10 39Z" fill="#755087"/><path d="M30 74h40v26H30Z" fill="#3a816b"/><circle cx="50" cy="35" r="30" fill="#99c6ca" stroke="#d6f2e3" stroke-width="2"/><path d="M25 40q15-23 50-10M25 46q30 14 49-2M34 14q10 3 18-1" fill="none" stroke="#dfefdd" stroke-width="4" opacity=".7"/>'}
  ];
  let labMode='drones',activeVillain=0,villainHP=8;
  const villainArt=v=>'<svg viewBox="0 0 100 105" aria-hidden="true">'+v.svg+'</svg>';
  const modes={classic:{points:100,hint:'Classic line: aim precisely at a drone for 100 points.'},burst:{points:75,hint:'Triple burst: three strands catch drones in a wider cone. 75 points per drone.'},net:{points:50,hint:'Web net: place a sticky web between nearby drones to catch a group. 50 points per drone.'}};
  let mode='classic',score=0,hits=0,shots=0,streak=0,bestStreak=0,best=0,remaining=30,challenge=false,finished=false,lastTick=0,interval=null,visiblePage=location.hash.slice(1)||'home';
  let movingTargets=!noMotion,targetSpeed=1,lastMotion=0;function makeTarget([x,y],id){return{id,x,y,caught:false,vx:(id%2?1:-1)*(38+id*6),vy:(id%3?1:-1)*(19+id*4)}}let targets=base.map(makeTarget);let generation=0;const timers=new Set();
  try{best=Math.max(0,Number(localStorage.getItem('assemble-web-best'))||0)}catch{}
  const el=id=>document.getElementById(id);el('best-score').textContent=best;
  function sync(){el('score').textContent=score;el('hits').textContent=`${hits}/${shots}`;el('streak').textContent=streak;el('timer').textContent=challenge?`${Math.ceil(remaining)}s LEFT`:finished?'ROUND COMPLETE':'FREE PLAY'}
  function drawTargets(){layer.innerHTML=targets.map(t=>`<button class="target ${t.caught?'caught':''} ${t.id===5?'gold':''} ${labMode==='villains'?'villain-target':''}" data-target="${t.id}" style="left:${t.x/10}%;top:${t.y/5.6}%" aria-label="${labMode==='villains'?villains[activeVillain].name+' weak point':t.id===5?'Gold bonus drone':'Training drone'} ${t.id+1}: shoot ${mode==='classic'?'classic line':mode==='burst'?'triple burst':'web net'}" ${t.caught?'disabled':''}>${labMode==='villains'?villainArt(villains[activeVillain]):'<svg viewBox="0 0 30 30" aria-hidden="true"><path d="M15 4 26 10v11L15 27 4 21V10Z" fill="none" stroke="currentColor" stroke-width="1.5"/><circle cx="15" cy="15" r="5" fill="none" stroke="currentColor" stroke-width="1.5"/><path d="M15 1v8m0 12v8M1 15h8m12 0h8" stroke="currentColor"/></svg>'}</button>`).join('');layer.querySelectorAll('[data-target]').forEach(b=>b.onclick=e=>{e.stopPropagation();const t=targets[+b.dataset.target];if(!t.caught){shoot(t.x,t.y);if(e.detail===0)layer.querySelector('.target:not([disabled])')?.focus()}})}
  function svg(tag,attrs,parent){const n=document.createElementNS(svgNS,tag);Object.entries(attrs).forEach(([k,v])=>n.setAttribute(k,v));parent.append(n);return n}
  function strand(g,x,y,offset=0){svg('path',{d:`M 500 555 Q ${500+(x-500)*.5+offset} ${555+(y-555)*.55} ${x} ${y}`,class:'web-shot',pathLength:1},g)}
  function webNet(g,x,y,radius){const points=10;for(let i=0;i<points;i++){const a=i/points*Math.PI*2;svg('line',{x1:x,y1:y,x2:x+Math.cos(a)*radius,y2:y+Math.sin(a)*radius,class:'web-net'},g)}for(let ring=1;ring<=4;ring++){const r=radius*ring/4;let d='';for(let i=0;i<=points;i++){const a=i/points*Math.PI*2;d+=(i?' L ':'M ')+(x+Math.cos(a)*r)+' '+(y+Math.sin(a)*r)}svg('path',{d,class:'web-net'},g)}}
  function effect(x,y,caught,gained){const g=svg('g',{class:'web-effect-group '+(mode==='net'?'net-effect':'')},effects);if(mode==='classic'){strand(g,x,y);strand(g,x-3,y,8);strand(g,x+3,y,-8);webNet(g,x,y,23)}else if(mode==='burst'){for(const delta of[-.22,0,.22]){const dx=x-500,dy=y-555,a=Math.atan2(dy,dx)+delta,d=Math.hypot(dx,dy);const xx=500+Math.cos(a)*d,yy=555+Math.sin(a)*d;strand(g,xx,yy,delta*80);webNet(g,xx,yy,22)}}else{strand(g,x,y);webNet(g,x,y,150)}if(caught.length){svg('circle',{cx:x,cy:y,r:35,class:'impact-ring'},g);for(let k=0;k<8;k++){const a=k*Math.PI/4;svg('line',{x1:x+Math.cos(a)*40,y1:y+Math.sin(a)*40,x2:x+Math.cos(a)*57,y2:y+Math.sin(a)*57,class:'impact-spark'},g)}const text=svg('text',{x,y:y-28,'text-anchor':'middle',class:'web-score-text'},g);text.textContent='+'+gained}while(effects.childElementCount>12)effects.firstElementChild.remove();const t=setTimeout(()=>{g.remove();timers.delete(t)},4200);timers.add(t)}
  function isHit(target,x,y){if(mode==='classic')return Math.hypot(target.x-x,target.y-y)<53;if(mode==='net')return Math.hypot(target.x-x,target.y-y)<180;const aim=Math.atan2(y-555,x-500),angle=Math.atan2(target.y-555,target.x-500);const difference=Math.atan2(Math.sin(angle-aim),Math.cos(angle-aim));return Math.abs(difference)<.27&&Math.abs(Math.hypot(target.x-500,target.y-555)-Math.hypot(x-500,y-555))<190}
  function respawn(t,version){const timeout=setTimeout(()=>{timers.delete(timeout);if(version!==generation||finished)return;const [x,y]=base[t.id];t.x=x+(Math.random()-.5)*90;t.y=y+(Math.random()-.5)*45;t.caught=false;drawTargets()},800);timers.add(timeout)}
  function shoot(x,y){if(finished)return;shots++;const caught=targets.filter(t=>!t.caught&&isHit(t,x,y));caught.forEach(t=>{t.caught=true;respawn(t,generation)});hits+=caught.length;streak=caught.length?streak+1:0;bestStreak=Math.max(streak,bestStreak);const gained=caught.reduce((sum,t)=>sum+modes[mode].points*(t.id===5?2:1),0);score+=gained;const feedback=el('shot-feedback');feedback.textContent=caught.length?`${caught.length>1?'MULTI CATCH':'CLEAN HIT'} +${gained}`:'MISSED — TRY AGAIN';feedback.dataset.hit=String(caught.length>0);if(!noMotion)document.querySelector('.shooter').animate?.([{transform:'translateX(-50%) rotate(-8deg)'},{transform:'translateX(-50%) rotate(0deg)'}],{duration:180});if(labMode==='villains'&&caught.length){villainHP=Math.max(0,villainHP-caught.length*(mode==='classic'?2:1));updateVillainHealth()}effect(x,y,caught,gained);sync();drawTargets();el('lab-announcement').textContent=caught.length?`${caught.length} target${caught.length>1?'s':''} caught. ${score} points.`:'Missed. Aim at a target and try again.';if(labMode==='villains'&&villainHP===0){score+=500;sync();finish(true)}}
  stage.addEventListener('click',e=>{if(e.target.closest('button'))return;const rect=stage.getBoundingClientRect();if(!rect.width||!rect.height)return;shoot((e.clientX-rect.left)/rect.width*1000,(e.clientY-rect.top)/rect.height*560)});
  document.querySelectorAll('[data-web]').forEach(b=>b.onclick=()=>{mode=b.dataset.web;document.querySelectorAll('[data-web]').forEach(btn=>{btn.classList.toggle('selected',btn===b);btn.setAttribute('aria-pressed',String(btn===b))});el('web-hint').textContent=labMode==='villains'?(mode==='classic'?'Precision web: 2 containment points per weak point.':'Wide catch: 1 containment point per weak point caught.'):modes[mode].hint;drawTargets()});
  function clearEffects(){effects.replaceChildren()}
  function reset(){generation++;timers.forEach(clearTimeout);timers.clear();if(interval)clearInterval(interval);interval=null;challenge=false;finished=false;score=hits=shots=streak=bestStreak=0;el('shot-feedback').textContent='';remaining=30;targets=(labMode==='villains'?base.slice(0,3):base).map(makeTarget);villainHP=8;updateVillainHealth();el('round-result').hidden=true;el('start-challenge').textContent='30-second challenge ↗';el('start-challenge').disabled=false;clearEffects();sync();drawTargets()}
  function finish(won=false){const scoredChallenge=challenge;challenge=false;finished=true;if(interval)clearInterval(interval);interval=null;if(scoredChallenge){best=Math.max(score,best);try{localStorage.setItem('assemble-web-best',String(best))}catch{}}el('best-score').textContent=best;document.querySelector('#round-result h2').textContent=labMode==='villains'?(won?villains[activeVillain].name+' contained!':'The villain escaped.'):'Nice shooting, Spidey.';el('round-summary').textContent=`${won?'Containment bonus: +500. ':''}${score} points · ${hits} targets caught · ${shots} shots. Best streak: ${bestStreak}. Best score: ${best}.`;el('round-result').hidden=false;el('start-challenge').textContent='New challenge ↗';el('start-challenge').disabled=false;el('lab-announcement').textContent=`Training complete. ${score} points.`;sync();el('play-again').focus()}
  function tick(){const now=performance.now(),elapsed=Math.max(0,(now-lastTick)/1000);lastTick=now;if(!challenge||visiblePage!=='weblab'||document.hidden)return;remaining=Math.max(0,remaining-elapsed);sync();if(remaining<=0)finish()}
  function start(){reset();challenge=true;lastTick=performance.now();el('start-challenge').textContent='Challenge running…';el('start-challenge').disabled=true;sync();interval=setInterval(tick,100);el('lab-announcement').textContent='Challenge started. Thirty seconds. Catch as many drones as you can.';layer.querySelector('.target').focus()}
  el('clear-webs').onclick=clearEffects;el('reset-lab').onclick=reset;el('start-challenge').onclick=start;el('play-again').onclick=start;
  window.addEventListener('assemble-page',e=>{visiblePage=e.detail;lastTick=performance.now();if(challenge)el('timer').textContent=visiblePage==='weblab'?Math.ceil(remaining)+'s LEFT':'PAUSED'});document.addEventListener('visibilitychange',()=>lastTick=performance.now());
  function updateMotionControl(){el('target-motion').textContent=movingTargets?'Pause targets Ⅱ':'Resume targets ▶';el('target-motion').setAttribute('aria-pressed',String(!movingTargets));stage.classList.toggle('targets-paused',!movingTargets)}el('target-motion').onclick=()=>{movingTargets=!movingTargets;lastMotion=performance.now();updateMotionControl()};el('target-speed').onchange=()=>{targetSpeed=Number(el('target-speed').value)||1};function motion(now){requestAnimationFrame(motion);const dt=Math.min(Math.max((now-lastMotion)/1000,0),.05);lastMotion=now;if(!movingTargets||visiblePage!=='weblab'||document.hidden||finished)return;const boost=challenge?1+(30-remaining)/60:1;for(const t of targets){const node=layer.querySelector('[data-target="'+t.id+'"]');if(t.caught||!node||document.activeElement===node)continue;t.x+=t.vx*dt*targetSpeed*boost;t.y+=t.vy*dt*targetSpeed*boost;if(t.x<85){t.x=85;t.vx=Math.abs(t.vx)}if(t.x>915){t.x=915;t.vx=-Math.abs(t.vx)}if(t.y<95){t.y=95;t.vy=Math.abs(t.vy)}if(t.y>430){t.y=430;t.vy=-Math.abs(t.vy)}node.style.left=(t.x/10)+'%';node.style.top=(t.y/5.6)+'%'}}updateMotionControl();requestAnimationFrame(motion);const reticle=el('aim-reticle');stage.addEventListener('pointermove',e=>{if(e.pointerType!=='mouse'||finished)return;const r=stage.getBoundingClientRect();if(!r.width)return;reticle.hidden=false;reticle.style.left=((e.clientX-r.left)/r.width*100)+'%';reticle.style.top=((e.clientY-r.top)/r.height*100)+'%'});stage.addEventListener('pointerleave',()=>reticle.hidden=true);document.addEventListener('keydown',e=>{if(visiblePage!=='weblab'||['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)||e.ctrlKey||e.metaKey||e.altKey)return;const keys={'1':'classic','2':'burst','3':'net'};if(keys[e.key]){e.preventDefault();document.querySelector('[data-web="'+keys[e.key]+'"]').click()}});
  function updateVillainHealth(){el('villain-label').textContent=villains[activeVillain].name;el('villain-health-bar').style.width=(villainHP/8*100)+'%';el('villain-health-text').textContent=villainHP+' / 8 containment points';el('villain-health').setAttribute('role','progressbar');el('villain-health').setAttribute('aria-valuemin','0');el('villain-health').setAttribute('aria-valuemax','8');el('villain-health').setAttribute('aria-valuenow',String(villainHP))}function renderVillain(){const v=villains[activeVillain];el('villain-backdrop').innerHTML=villainArt(v)+'<strong>'+v.name+'</strong>';el('villain-brief').textContent=v.brief;stage.style.setProperty('--villain-color',v.color);document.querySelectorAll('[data-villain]').forEach(b=>b.setAttribute('aria-pressed',String(+b.dataset.villain===activeVillain)));updateVillainHealth()}el('villain-picks').innerHTML=villains.map((v,i)=>'<button data-villain="'+i+'" aria-pressed="'+(i===0)+'" style="--villain-color:'+v.color+'">'+villainArt(v)+'<span>'+v.name+'</span></button>').join('');document.querySelectorAll('[data-villain]').forEach(b=>b.onclick=()=>{activeVillain=+b.dataset.villain;renderVillain();reset()});document.querySelectorAll('[data-lab-mode]').forEach(b=>b.onclick=()=>{labMode=b.dataset.labMode;document.querySelectorAll('[data-lab-mode]').forEach(btn=>{btn.setAttribute('aria-pressed',String(btn===b));btn.classList.toggle('selected',btn===b)});el('villain-selection').hidden=labMode!=='villains';el('villain-backdrop').hidden=labMode!=='villains';el('villain-health').hidden=labMode!=='villains';stage.classList.toggle('villain-encounter',labMode==='villains');el('target-reward-note').innerHTML=labMode==='villains'?'Contain the villain for a +500 bonus':'<span class="gold-drone-dot"></span> Gold drone = double points';el('web-hint').textContent=labMode==='villains'?(mode==='classic'?'Precision web: 2 containment points per weak point.':'Wide catch: 1 containment point per weak point caught.'):modes[mode].hint;renderVillain();reset()});renderVillain();
  reset();
})();
